pub(super) async fn delete_collection(
    &self,
    collection_name: &str,
) -> Result<bool, StorageError> {
    let _collection_create_guard = self.collection_create_lock.lock().await;

    self.alias_persistence
        .write()
        .await
        .remove_collection(collection_name)?;   // removes aliases MAPPING TO collection_name; never resolves collection_name AS an alias

    let to_delete;
    let result;
    let collection_path = self.get_collection_path(collection_name);
    let safe_delete_path = self.storage_config.storage_path.join(".deleted");

    let removed_opt = self.collections.write().await.remove(collection_name);  // LITERAL name lookup — no resolve_name() call
    if let Some(removed) = removed_opt {
        ... // stop collection, delete files
        result = true;
    } else {
        // we hold the collection_create lock to make sure no one is creating this collection
        // otherwise we would delete its content now
        if collection_path.exists() { ... }
        else { to_delete = None; }
        result = false;   // <- missing name: Ok(false), NO StorageError::not_found, NO 404
    }
    ...
    Ok(result)
}
```
Contrast — the READ face resolves aliases and 404s (lib/storage/src/content_manager/toc/mod.rs:407-420):
```rust
fn resolve_name(
    collection_name: &str,
    collections: &Collections,
    aliases: &AliasPersistence,
) -> Result<String, StorageError> {
    let alias_collection_name = aliases.get(collection_name);
    let resolved_name = match alias_collection_name {
        None => collection_name.to_string(),
        Some(resolved_alias) => resolved_alias,
    };
    collections.validate_collection_exists(&resolved_name)?;  // -> StorageError::not_found("Collection `{name}` doesn't exist!") -> HTTP 404
    Ok(resolved_name)
}
```
And the actix wrapper (src/actix/helpers.rs:61-65): Ok(res) -> HttpResponse::Ok().json(ApiResponse{ result: Some(res), status: ApiStatus::Ok, .. }) — so Ok(false) serializes exactly as the observed {"result":false,"status":"ok",...} with HTTP 200. Repo OpenAPI (openapi-collections.ytt.yaml:89-110) documents param 'Name of the collection to delete' and responses #@ response(type("boolean")) = 200 + generic 4XX envelope.
